// Command shop is models' example: an app whose models sqlc generates, with
// labels for its enum values, tables and columns generated by models and
// declared by i18n. It prints the labels in the source language and, with a
// database in DATABASE_URL, a page of paid orders through a listing.
package main

//go:generate go tool genx

import (
	"context"
	"fmt"
	"os"

	"github.com/jackc/pgx/v5"

	"github.com/epistemer/models/examples/shop/models"
	"github.com/epistemer/models/listing"
)

func main() {
	ctx := context.Background() // no translator: the code's English text
	fmt.Println(models.L10nOrder.T(ctx))
	for _, s := range models.AllOrderStatusValues() {
		fmt.Printf("  %s: %s\n", models.L10nOrder_Status.T(ctx), s.Label().T(ctx))
	}
	fmt.Println(models.L10n("table.shop_customer.email").T(ctx))

	if url := os.Getenv("DATABASE_URL"); url != "" {
		if err := listPaid(ctx, url); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
}

// listPaid prints the first page of paid orders, newest first, and how many
// there are.
func listPaid(ctx context.Context, url string) error {
	conn, err := pgx.Connect(ctx, url)
	if err != nil {
		return err
	}
	defer conn.Close(ctx)
	var q models.Listings = models.New(conn)
	orders, total, err := q.ListShopOrderListView(ctx, listing.Query{
		Filters: []listing.Filter{{Column: "status", Op: listing.Eq, Value: models.OrderStatusPaid}},
		Sort:    []listing.Sort{{Column: "placed_at", Desc: true}, {Column: "id"}},
		Limit:   20,
	})
	if err != nil {
		return err
	}
	fmt.Printf("%s: %d\n", models.L10nOrderListView.T(ctx), total)
	for _, o := range orders {
		fmt.Printf("  %d %s %s\n", o.ID, o.Email, o.Status.Label().T(ctx))
	}
	return nil
}
